-- ============================================================================
-- Canonical database schema for the Construction Project Management &
-- Accounting System, as provisioned directly against the Supabase Postgres
-- instance this project connects to. This is the SOURCE OF TRUTH for table
-- shapes, constraints, enum values, and indexes -- Django app models must
-- match it exactly (adopted via `migrate --fake` / `--fake-initial` rather
-- than re-created, since the tables already exist here).
--
-- Provided by the team (originally run by hand against Supabase before any
-- Django migration existed) and committed here on 2026-08-31 so it's no
-- longer something only reconstructable by inspecting the live database or
-- reading chat history. If the live schema is ever altered, update this
-- file to match in the same change.
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$ BEGIN CREATE TYPE contractor_status_enum AS ENUM ('ACTIVE','INACTIVE','TERMINATED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE project_status_enum AS ENUM ('PLANNING','ACTIVE','ON_HOLD','COMPLETED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE phase_status_enum AS ENUM ('NOT_STARTED','IN_PROGRESS','COMPLETED','ON_HOLD'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE contractor_assignment_status_enum AS ENUM ('ASSIGNED','IN_PROGRESS','COMPLETED','RELEASED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE budget_status_enum AS ENUM ('DRAFT','APPROVED','REVISED','CLOSED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE change_order_status_enum AS ENUM ('PENDING','APPROVED','REJECTED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE po_status_enum AS ENUM ('DRAFT','SUBMITTED','APPROVED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE expense_status_enum AS ENUM ('PENDING','APPROVED','PAID','REJECTED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE invoice_status_enum AS ENUM ('DRAFT','SENT','PARTIALLY_PAID','PAID','OVERDUE','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE transaction_status_enum AS ENUM ('DRAFT','POSTED','VOIDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE project_type_enum AS ENUM ('WHOLE_BUILDING','MULTI_UNIT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE unit_status_enum AS ENUM ('AVAILABLE','RESERVED','SOLD'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE employment_status_enum AS ENUM ('ACTIVE','ON_LEAVE','TERMINATED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE movement_type_enum AS ENUM ('IN','OUT','RETURN','TRANSFER','ADJUSTMENT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE timesheet_status_enum AS ENUM ('DRAFT','SUBMITTED','APPROVED','REJECTED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS company_details (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL, registration_number VARCHAR(100), address TEXT, phone VARCHAR(50), email VARCHAR(255), website VARCHAR(255), currency UUID NOT NULL, tax_information TEXT, logo VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username VARCHAR(150) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, role VARCHAR(100) NOT NULL, phone VARCHAR(50), is_active BOOLEAN NOT NULL DEFAULT true, last_login TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS permissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code VARCHAR(150) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS tax_rates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL, rate DECIMAL(8,4) NOT NULL, tax_type VARCHAR(50) NOT NULL, effective_date DATE NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS clients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL, company_name VARCHAR(255), phone VARCHAR(50), email VARCHAR(255), address TEXT, tax_id VARCHAR(100), notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL, company_name VARCHAR(255), phone VARCHAR(50), email VARCHAR(255), address TEXT, tax_number VARCHAR(100), payment_terms VARCHAR(255), notes TEXT, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contractors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL, company_name VARCHAR(255), phone TEXT, email VARCHAR(255), contract_details TEXT, specialization VARCHAR(255), payment_terms VARCHAR(255), rate DECIMAL(18,2), status contractor_status_enum NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employees (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_number VARCHAR(100) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, phone VARCHAR(50), email VARCHAR(255), position VARCHAR(150), department VARCHAR(150), employment_status employment_status_enum NOT NULL DEFAULT 'ACTIVE', labor_rate DECIMAL(18,2), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS accounts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), parent_account_id UUID REFERENCES accounts(id), code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, account_type VARCHAR(30) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), manager_id UUID REFERENCES employees(id), name VARCHAR(255) NOT NULL, code VARCHAR(100) NOT NULL UNIQUE, location TEXT, project_type project_type_enum NOT NULL, estimated_sale_price DECIMAL(18,2), actual_sale_price DECIMAL(18,2), buyer_id UUID REFERENCES clients(id), start_date DATE NOT NULL, expected_completion_date DATE, actual_completion_date DATE, contract_value DECIMAL(18,2) NOT NULL, status project_status_enum NOT NULL DEFAULT 'PLANNING', description TEXT, is_archived BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS units (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, buyer_id UUID REFERENCES clients(id), unit_number VARCHAR(50) NOT NULL, unit_type VARCHAR(50), area_sqft DECIMAL(10,2), target_price DECIMAL(18,2) NOT NULL, actual_sale_price DECIMAL(18,2), status unit_status_enum NOT NULL DEFAULT 'AVAILABLE', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now(), UNIQUE(project_id,unit_number));
CREATE TABLE IF NOT EXISTS project_phases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, description TEXT, start_date DATE, end_date DATE, responsible_emp_id UUID REFERENCES employees(id), status phase_status_enum NOT NULL DEFAULT 'NOT_STARTED', progress_percentage DECIMAL(5,2) NOT NULL DEFAULT 0, sequence_number INTEGER NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_employees (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, employee_id UUID NOT NULL REFERENCES employees(id), assigned_at DATE NOT NULL, released_at DATE, role_on_project VARCHAR(150), UNIQUE(project_id,employee_id));
CREATE TABLE IF NOT EXISTS timesheets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), employee_id UUID NOT NULL REFERENCES employees(id), project_id UUID NOT NULL REFERENCES projects(id), phase_id UUID REFERENCES project_phases(id), work_date DATE NOT NULL, hours_worked DECIMAL(5,2) NOT NULL CHECK(hours_worked>0 AND hours_worked<=24), hourly_rate DECIMAL(18,2) NOT NULL, total_cost DECIMAL(18,2) GENERATED ALWAYS AS (hours_worked*hourly_rate) STORED, description TEXT, status timesheet_status_enum NOT NULL DEFAULT 'DRAFT', approved_by UUID REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_contractors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, contractor_id UUID NOT NULL REFERENCES contractors(id), contract_amount DECIMAL(18,2), assigned_at DATE NOT NULL, released_at DATE, status contractor_assignment_status_enum NOT NULL DEFAULT 'ASSIGNED');
CREATE TABLE IF NOT EXISTS project_budgets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, total_budget DECIMAL(18,2) NOT NULL, status budget_status_enum NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS budget_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), budget_id UUID NOT NULL REFERENCES project_budgets(id) ON DELETE CASCADE, phase_id UUID REFERENCES project_phases(id), category VARCHAR(50) NOT NULL, description TEXT, budgeted_amount DECIMAL(18,2) NOT NULL);
CREATE TABLE IF NOT EXISTS change_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id), number VARCHAR(100) NOT NULL, description TEXT NOT NULL, reason TEXT, amount DECIMAL(18,2) NOT NULL, requested_by UUID REFERENCES users(id), approved_by UUID REFERENCES users(id), date DATE NOT NULL, status change_order_status_enum NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS material_categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(150) NOT NULL UNIQUE, description TEXT);
CREATE TABLE IF NOT EXISTS materials (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID NOT NULL REFERENCES material_categories(id), name VARCHAR(255) NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, unit VARCHAR(50) NOT NULL, description TEXT, standard_cost DECIMAL(18,2), tax_rate_id UUID REFERENCES tax_rates(id), default_supplier_id UUID REFERENCES suppliers(id), minimum_stock_level DECIMAL(18,3) NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS warehouses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(255) NOT NULL, location TEXT, is_active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS stocks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), warehouse_id UUID NOT NULL REFERENCES warehouses(id), material_id UUID NOT NULL REFERENCES materials(id), quantity DECIMAL(18,3) NOT NULL DEFAULT 0, updated_at TIMESTAMP NOT NULL DEFAULT now(), UNIQUE(warehouse_id,material_id));
CREATE TABLE IF NOT EXISTS stock_movements (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), material_id UUID NOT NULL REFERENCES materials(id), warehouse_id UUID NOT NULL REFERENCES warehouses(id), project_id UUID REFERENCES projects(id), quantity DECIMAL(18,3) NOT NULL, movement_type movement_type_enum NOT NULL, movement_date TIMESTAMP NOT NULL DEFAULT now(), user_id UUID NOT NULL REFERENCES users(id), reference VARCHAR(255), notes TEXT);
CREATE TABLE IF NOT EXISTS purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID NOT NULL REFERENCES suppliers(id), project_id UUID REFERENCES projects(id), po_number VARCHAR(100) NOT NULL UNIQUE, order_date DATE NOT NULL, expected_delivery_date DATE, subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, status po_status_enum NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_order_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id) ON DELETE CASCADE, material_id UUID NOT NULL REFERENCES materials(id), description TEXT, quantity DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,2) NOT NULL, tax_rate_id UUID REFERENCES tax_rates(id), tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS goods_receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id UUID NOT NULL REFERENCES purchase_orders(id), receipt_number VARCHAR(100) NOT NULL UNIQUE, received_date DATE NOT NULL, warehouse_id UUID NOT NULL REFERENCES warehouses(id), received_by UUID REFERENCES employees(id), notes TEXT, created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS goods_receipt_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), goods_receipt_id UUID NOT NULL REFERENCES goods_receipts(id) ON DELETE CASCADE, purchase_order_item_id UUID NOT NULL REFERENCES purchase_order_items(id), quantity_received DECIMAL(18,3) NOT NULL, notes TEXT);
CREATE TABLE IF NOT EXISTS expense_categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(150) NOT NULL UNIQUE, description TEXT, account_id UUID REFERENCES accounts(id));
CREATE TABLE IF NOT EXISTS expenses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id), category_id UUID NOT NULL REFERENCES expense_categories(id), supplier_id UUID REFERENCES suppliers(id), employee_id UUID REFERENCES employees(id), contractor_id UUID REFERENCES contractors(id), expense_date DATE NOT NULL, description TEXT NOT NULL, amount DECIMAL(18,2) NOT NULL, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, payment_method VARCHAR(50), status expense_status_enum NOT NULL DEFAULT 'PENDING', notes TEXT, created_by UUID REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_id UUID NOT NULL REFERENCES clients(id), project_id UUID REFERENCES projects(id), unit_id UUID REFERENCES units(id), invoice_number VARCHAR(100) NOT NULL UNIQUE, invoice_date DATE NOT NULL, due_date DATE, subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, discount_amount DECIMAL(18,2) DEFAULT 0, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, status invoice_status_enum NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client_invoice_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_invoice_id UUID NOT NULL REFERENCES client_invoices(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,2) NOT NULL, discount_amount DECIMAL(18,2) DEFAULT 0, tax_rate_id UUID REFERENCES tax_rates(id), tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS supplier_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID NOT NULL REFERENCES suppliers(id), purchase_order_id UUID REFERENCES purchase_orders(id), invoice_number VARCHAR(100) NOT NULL UNIQUE, invoice_date DATE NOT NULL, due_date DATE, subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0, status invoice_status_enum NOT NULL DEFAULT 'DRAFT', created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_invoice_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_invoice_id UUID NOT NULL REFERENCES supplier_invoices(id) ON DELETE CASCADE, material_id UUID REFERENCES materials(id), description TEXT NOT NULL, quantity DECIMAL(18,3), unit_price DECIMAL(18,2), tax_rate_id UUID REFERENCES tax_rates(id), tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, total_amount DECIMAL(18,2) NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_number VARCHAR(100) NOT NULL UNIQUE, payment_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, direction VARCHAR(20) NOT NULL CHECK(direction IN ('INCOMING','OUTGOING')), payment_method VARCHAR(50) NOT NULL, client_id UUID REFERENCES clients(id), supplier_id UUID REFERENCES suppliers(id), employee_id UUID REFERENCES employees(id), contractor_id UUID REFERENCES contractors(id), reference VARCHAR(255), notes TEXT, created_by UUID NOT NULL REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_allocations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID NOT NULL REFERENCES payments(id), client_invoice_id UUID REFERENCES client_invoices(id), supplier_invoice_id UUID REFERENCES supplier_invoices(id), allocated_amount DECIMAL(18,2) NOT NULL, CHECK((client_invoice_id IS NOT NULL AND supplier_invoice_id IS NULL) OR (client_invoice_id IS NULL AND supplier_invoice_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), payment_id UUID NOT NULL UNIQUE REFERENCES payments(id), receipt_number VARCHAR(100) NOT NULL UNIQUE, receipt_date DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, reference VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS financial_transactions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_number VARCHAR(100) NOT NULL UNIQUE, transaction_date DATE NOT NULL, description TEXT NOT NULL, reference VARCHAR(255), project_id UUID REFERENCES projects(id), client_id UUID REFERENCES clients(id), supplier_id UUID REFERENCES suppliers(id), status transaction_status_enum NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL REFERENCES users(id), posted_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transaction_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id UUID NOT NULL REFERENCES financial_transactions(id) ON DELETE CASCADE, account_id UUID NOT NULL REFERENCES accounts(id), description TEXT, debit DECIMAL(18,2) NOT NULL DEFAULT 0, credit DECIMAL(18,2) NOT NULL DEFAULT 0, project_id UUID REFERENCES projects(id), CHECK(debit>=0 AND credit>=0), CHECK(NOT(debit>0 AND credit>0)));
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), uploaded_by UUID NOT NULL REFERENCES users(id), file_name VARCHAR(255) NOT NULL, file_path VARCHAR(500) NOT NULL, file_type VARCHAR(100), file_size BIGINT, document_type VARCHAR(100), entity_type VARCHAR(100) NOT NULL, entity_id UUID NOT NULL, uploaded_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), notification_type VARCHAR(100) NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, entity_type VARCHAR(100), entity_id UUID, is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(100) NOT NULL, entity_id UUID NOT NULL, old_values JSONB, new_values JSONB, ip_address INET, created_at TIMESTAMP NOT NULL DEFAULT now());

DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['company_details','users','permissions','tax_rates','clients','suppliers','contractors','employees','accounts','projects','units','project_phases','project_employees','timesheets','project_contractors','project_budgets','budget_items','change_orders','material_categories','materials','warehouses','stocks','stock_movements','purchase_orders','purchase_order_items','goods_receipts','goods_receipt_items','expense_categories','expenses','client_invoices','client_invoice_items','supplier_invoices','supplier_invoice_items','payments','payment_allocations','receipts','financial_transactions','transaction_lines','documents','notifications','audit_logs'] LOOP EXECUTE format('ALTER TABLE %I DISABLE ROW LEVEL SECURITY',t); END LOOP; END $$;

CREATE INDEX IF NOT EXISTS idx_accounts_parent ON accounts(parent_account_id);
CREATE INDEX IF NOT EXISTS idx_projects_manager ON projects(manager_id); CREATE INDEX IF NOT EXISTS idx_projects_buyer ON projects(buyer_id); CREATE INDEX IF NOT EXISTS idx_projects_status ON projects(status);
CREATE INDEX IF NOT EXISTS idx_units_project ON units(project_id); CREATE INDEX IF NOT EXISTS idx_units_buyer ON units(buyer_id); CREATE INDEX IF NOT EXISTS idx_units_status ON units(status);
CREATE INDEX IF NOT EXISTS idx_phases_project ON project_phases(project_id); CREATE INDEX IF NOT EXISTS idx_phases_employee ON project_phases(responsible_emp_id); CREATE INDEX IF NOT EXISTS idx_phases_status ON project_phases(status);
CREATE INDEX IF NOT EXISTS idx_project_employees_project ON project_employees(project_id); CREATE INDEX IF NOT EXISTS idx_project_employees_employee ON project_employees(employee_id);
CREATE INDEX IF NOT EXISTS idx_timesheets_employee ON timesheets(employee_id); CREATE INDEX IF NOT EXISTS idx_timesheets_project ON timesheets(project_id); CREATE INDEX IF NOT EXISTS idx_timesheets_phase ON timesheets(phase_id); CREATE INDEX IF NOT EXISTS idx_timesheets_approved_by ON timesheets(approved_by); CREATE INDEX IF NOT EXISTS idx_timesheets_status ON timesheets(status); CREATE INDEX IF NOT EXISTS idx_timesheets_work_date ON timesheets(work_date);
CREATE INDEX IF NOT EXISTS idx_project_contractors_project ON project_contractors(project_id); CREATE INDEX IF NOT EXISTS idx_project_contractors_contractor ON project_contractors(contractor_id); CREATE INDEX IF NOT EXISTS idx_project_contractors_status ON project_contractors(status);
CREATE INDEX IF NOT EXISTS idx_budgets_project ON project_budgets(project_id); CREATE INDEX IF NOT EXISTS idx_budget_items_budget ON budget_items(budget_id); CREATE INDEX IF NOT EXISTS idx_budget_items_phase ON budget_items(phase_id);
CREATE INDEX IF NOT EXISTS idx_change_orders_project ON change_orders(project_id); CREATE INDEX IF NOT EXISTS idx_change_orders_requested_by ON change_orders(requested_by); CREATE INDEX IF NOT EXISTS idx_change_orders_approved_by ON change_orders(approved_by); CREATE INDEX IF NOT EXISTS idx_change_orders_status ON change_orders(status);
CREATE INDEX IF NOT EXISTS idx_materials_category ON materials(category_id); CREATE INDEX IF NOT EXISTS idx_materials_tax_rate ON materials(tax_rate_id); CREATE INDEX IF NOT EXISTS idx_materials_supplier ON materials(default_supplier_id);
CREATE INDEX IF NOT EXISTS idx_stocks_warehouse ON stocks(warehouse_id); CREATE INDEX IF NOT EXISTS idx_stocks_material ON stocks(material_id);
CREATE INDEX IF NOT EXISTS idx_stock_movements_material ON stock_movements(material_id); CREATE INDEX IF NOT EXISTS idx_stock_movements_warehouse ON stock_movements(warehouse_id); CREATE INDEX IF NOT EXISTS idx_stock_movements_project ON stock_movements(project_id); CREATE INDEX IF NOT EXISTS idx_stock_movements_user ON stock_movements(user_id); CREATE INDEX IF NOT EXISTS idx_stock_movements_date ON stock_movements(movement_date);
CREATE INDEX IF NOT EXISTS idx_purchase_orders_supplier ON purchase_orders(supplier_id); CREATE INDEX IF NOT EXISTS idx_purchase_orders_project ON purchase_orders(project_id); CREATE INDEX IF NOT EXISTS idx_purchase_orders_creator ON purchase_orders(created_by); CREATE INDEX IF NOT EXISTS idx_purchase_orders_status ON purchase_orders(status);
CREATE INDEX IF NOT EXISTS idx_po_items_po ON purchase_order_items(purchase_order_id); CREATE INDEX IF NOT EXISTS idx_po_items_material ON purchase_order_items(material_id); CREATE INDEX IF NOT EXISTS idx_po_items_tax_rate ON purchase_order_items(tax_rate_id);
CREATE INDEX IF NOT EXISTS idx_goods_receipts_po ON goods_receipts(purchase_order_id); CREATE INDEX IF NOT EXISTS idx_goods_receipts_warehouse ON goods_receipts(warehouse_id); CREATE INDEX IF NOT EXISTS idx_goods_receipts_employee ON goods_receipts(received_by);
CREATE INDEX IF NOT EXISTS idx_gr_items_receipt ON goods_receipt_items(goods_receipt_id); CREATE INDEX IF NOT EXISTS idx_gr_items_po_item ON goods_receipt_items(purchase_order_item_id);
CREATE INDEX IF NOT EXISTS idx_expense_categories_account ON expense_categories(account_id);
CREATE INDEX IF NOT EXISTS idx_expenses_project ON expenses(project_id); CREATE INDEX IF NOT EXISTS idx_expenses_category ON expenses(category_id); CREATE INDEX IF NOT EXISTS idx_expenses_supplier ON expenses(supplier_id); CREATE INDEX IF NOT EXISTS idx_expenses_employee ON expenses(employee_id); CREATE INDEX IF NOT EXISTS idx_expenses_contractor ON expenses(contractor_id); CREATE INDEX IF NOT EXISTS idx_expenses_creator ON expenses(created_by); CREATE INDEX IF NOT EXISTS idx_expenses_status ON expenses(status);
CREATE INDEX IF NOT EXISTS idx_client_invoices_client ON client_invoices(client_id); CREATE INDEX IF NOT EXISTS idx_client_invoices_project ON client_invoices(project_id); CREATE INDEX IF NOT EXISTS idx_client_invoices_unit ON client_invoices(unit_id); CREATE INDEX IF NOT EXISTS idx_client_invoices_status ON client_invoices(status); CREATE INDEX IF NOT EXISTS idx_client_invoices_invoice_date ON client_invoices(invoice_date); CREATE INDEX IF NOT EXISTS idx_client_invoices_due_date ON client_invoices(due_date);
CREATE INDEX IF NOT EXISTS idx_client_invoice_items_invoice ON client_invoice_items(client_invoice_id); CREATE INDEX IF NOT EXISTS idx_client_invoice_items_tax_rate ON client_invoice_items(tax_rate_id);
CREATE INDEX IF NOT EXISTS idx_supplier_invoices_supplier ON supplier_invoices(supplier_id); CREATE INDEX IF NOT EXISTS idx_supplier_invoices_po ON supplier_invoices(purchase_order_id); CREATE INDEX IF NOT EXISTS idx_supplier_invoices_status ON supplier_invoices(status); CREATE INDEX IF NOT EXISTS idx_supplier_invoices_invoice_date ON supplier_invoices(invoice_date); CREATE INDEX IF NOT EXISTS idx_supplier_invoices_due_date ON supplier_invoices(due_date);
CREATE INDEX IF NOT EXISTS idx_supplier_invoice_items_invoice ON supplier_invoice_items(supplier_invoice_id); CREATE INDEX IF NOT EXISTS idx_supplier_invoice_items_material ON supplier_invoice_items(material_id); CREATE INDEX IF NOT EXISTS idx_supplier_invoice_items_tax_rate ON supplier_invoice_items(tax_rate_id);
